seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)
comp=str.maketrans("ACGT","TGCA")
rc=lambda s: s.translate(comp)[::-1]
r=rc(seq)
k=12
bset={}
for j in range(len(r)-k+1):
    bset.setdefault(r[j:j+k],[]).append(j)
res=[]
for i in range(n-k+1):
    km=seq[i:i+k]
    if km in bset:
        for j in bset[km]:
            L=k
            while i+L<n and j+L<n and seq[i+L]==r[j+L]:
                L+=1
            res.append((L,i,j))
res.sort(reverse=True)
print("max inverted repeat length:", res[0][0] if res else None)
for L,i,j in res[:8]:
    print(L,i,j,seq[i:i+L])

# direct repeats
dd={}
res2=[]
for j in range(n-k+1):
    dd.setdefault(seq[j:j+k],[]).append(j)
for i in range(n-k+1):
    km=seq[i:i+k]
    for j in dd[km]:
        if j<=i: continue
        L=k
        while i+L<n and j+L<n and seq[i+L]==seq[j+L]:
            L+=1
        res2.append((L,i,j))
res2.sort(reverse=True)
print("\nTop direct repeats:")
seen=set()
for L,i,j in res2[:15]:
    print(f"len={L} at {i} and {j}  {seq[i:i+L]}")
